                <button
                  type="button"
                  class="seat"
                  [class]="'state-' + cell.state"
                  data-testid="seat"
                  [attr.data-row]="cell.row"
                  [attr.data-column]="cell.column"
                  [attr.data-state]="cell.state"
                  [style.grid-column]="cell.track"
                  [disabled]="cell.state === 'unavailable'"
                  (click)="onSeatClick(cell)"
                >
                  {{ cell.column }}
                </button>
              } @else {
                <button
                  type="button"
                  class="couch"
                  [class]="'state-' + cell.state"
                  data-testid="couch"
                  [attr.data-row]="cell.row"
                  [attr.data-column-start]="cell.columnStart"
                  [attr.data-column-end]="cell.columnEnd"
                  [attr.data-state]="cell.state"
                  [style.grid-column]="cell.trackStart + ' / ' + (cell.trackEnd + 1)"
                  [disabled]="cell.state === 'unavailable'"
                  (click)="onCouchClick(cell)"
                >
                  {{ cell.columnStart }}-{{ cell.columnEnd }}
                </button>
              }
            }
          </div>
        }
      </div>
    </div>

    <div class="legend" data-testid="legend">
      @for (item of legendItems; track item.state) {
        <div class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
          <span class="swatch" [style.background-color]="item.color"></span>
          <span>{{ item.label }}</span>
        </div>
      }
    </div>

    <div class="selected-seats" data-testid="selected-seats">
      <p data-testid="selected-seats-count">Selected seats: {{ selectedCount() }}</p>
      @for (line of selectedLines(); track line.row) {
        <p data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.text }}</p>
      }
    </div>

    <div class="actions">
      <button type="button" data-testid="cancel-button" (click)="cancel()">Cancel</button>
      <button type="button" data-testid="continue-button" [disabled]="selectedCount() === 0" (click)="continueToSummary()">Continue</button>
    </div>
  </div>
}

