1	const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
2	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
3	
4	const ISO_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
5	
6	export function toIsoDate(date: Date): string {
7	  const year = date.getFullYear();
8	  const month = String(date.getMonth() + 1).padStart(2, '0');
9	  const day = String(date.getDate()).padStart(2, '0');
10	  return `${year}-${month}-${day}`;
11	}
12	
13	export function todayIsoDate(): string {
14	  return toIsoDate(new Date());
15	}
16	
17	/** Parses a strict `YYYY-MM-DD` string into a local-midnight Date, or null if invalid. */
18	export function parseIsoDate(value: string): Date | null {
19	  if (!ISO_DATE_PATTERN.test(value)) return null;
20	  const [year, month, day] = value.split('-').map(Number);
21	  const date = new Date(year, month - 1, day);
22	  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
23	    return null;
24	  }
25	  return date;
26	}
27	
28	export function isValidIsoDate(value: string): boolean {
29	  return parseIsoDate(value) !== null;
30	}
31	
32	export function isPastIsoDate(value: string, todayIso: string = todayIsoDate()): boolean {
33	  return value < todayIso;
34	}
35	
36	/** Resolves a raw `date` query param to the iso date that should be selected. */
37	export function resolveSelectedIsoDate(raw: string | null): string {
38	  const today = todayIsoDate();
39	  if (!raw || !isValidIsoDate(raw) || isPastIsoDate(raw, today)) {
40	    return today;
41	  }
42	  return raw;
43	}
44	
45	export function addDays(iso: string, days: number): string {
46	  const date = parseIsoDate(iso);
47	  if (!date) throw new Error(`Invalid iso date: ${iso}`);
48	  date.setDate(date.getDate() + days);
49	  return toIsoDate(date);
50	}
51	
52	export function weekdayName(iso: string): string {
53	  const date = parseIsoDate(iso);
54	  if (!date) throw new Error(`Invalid iso date: ${iso}`);
55	  return WEEKDAYS[date.getDay()];
56	}
57	
58	/** Formats `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
59	export function formatShowDate(iso: string, time: string): string {
60	  const date = parseIsoDate(iso);
61	  if (!date) throw new Error(`Invalid iso date: ${iso}`);
62	  const weekday = WEEKDAYS[date.getDay()];
63	  const month = MONTHS[date.getMonth()];
64	  return `${weekday} ${date.getDate()} ${month} ${time}`;
65	}
